"""Migrated Meridian CRM order_fulfilment workflow."""

from decimal import Decimal, InvalidOperation
from typing import Any


def _positive_amount(value: Any) -> bool:
    """Evaluate the legacy guard NVL(TOT_AMT, 0) > 0."""
    if value is None or value == "":
        value = 0

    try:
        return Decimal(str(value)) > Decimal(0)
    except (InvalidOperation, ValueError, TypeError):
        return False


def _account_on_credit_hold(record: dict, tables: dict) -> bool:
    """Return whether the first matching live account has CRED_HOLD='Y'."""
    account_id = record.get("ACCT_ID", "")

    for row in tables.get("ACCT_MASTER", []):
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get("ACCT_ID", "") == account_id:
            return row.get("CRED_HOLD", "") == "Y"

    return False


def _result(
    state: str,
    record: dict,
    audits: list[str],
    notifies: list[str],
    matched: bool,
) -> dict:
    return {
        "state": state,
        "record": record.copy(),
        "audits": audits,
        "notifies": notifies,
        "matched": matched,
    }


def fire(state: str, event: str, record: dict, tables: dict) -> dict:
    """Fire the first matching order_fulfilment workflow transition."""
    if state == "E" and event == "approve" and _positive_amount(
        record.get("TOT_AMT", "")
    ):
        return _result("A", record, ["ORD_APPR"], [], True)

    if state == "A" and event == "ship":
        return _result("S", record, ["ORD_SHIP"], ["shipped"], True)

    if state == "S" and event == "invoice":
        return _result("I", record, ["ORD_INV"], [], True)

    if state == "E" and event == "cancel":
        return _result("X", record, ["ORD_CANC"], [], True)

    if (
        state == "A"
        and event == "cancel"
        and not _account_on_credit_hold(record, tables)
    ):
        return _result("X", record, ["ORD_CANC"], [], True)

    if state == "I" and event == "cancel":
        return _result("X", record, ["ORD_CANC_INV"], ["credit_note"], True)

    return _result(state, record, ["WF_NOMATCH"], [], False)
